function target(service,floor){return TARGETS.find(t=>t[0]===service&&t[1]===floor)?.[3]||null}
function initial(service,f){if(f<0)return'blocked';if(f<=10)return'completed';if(service==='dreno')return'blocked';if(service==='corte')return f<17?'completed':f===17?'in_progress':'not_started';if(service==='fixacao')return f===11?'released':'not_started';if(service==='chumbamento')return f<=12?'completed':f===13?'released':'not_started';if(service==='afaq')return f===11?'in_progress':'not_started';if(service==='esgoto')return f===11?'completed':f===12?'in_progress':'not_started';return'not_started'}
