function fresh(){const day=seededDay();return{version:6,project:{name:'B2U',customer:'B2U Construtora e Incorporadora',startFloor:-2,targetFloor:25},settings:{averageWeeklyAbsences:2,unassignedAbsencesToday:1,unassignedCompensationDays:3,marginalEfficiency:.7,defaultWorkStart:'07:30'},today:structuredClone(day),days:{[BASE_DATE]:structuredClone(day)},checklistTemplates:defaultTemplates(),employees:EMP.map((name,i)=>({id:`emp-${i+1}`,name,attendance:'unmarked',compensationDays:0,frontKey:''})),issues:[{id:'dreno-bloqueado',type:'blocked',title:'Dreno aguardando liberação',floor:20,service:'dreno',reason:'Aguardando liberação da frente pela construtora',external:true,status:'open'}],history:[{service:'fixacao',floor:10,label:'Fixação 10º concluída'},{service:'esgoto',floor:11,label:'Esgoto 11º concluído'},{id:'afaq-10-20260818',service:'afaq',floor:10,date:BASE_DATE,time:'12:00',label:'AF/AQ 10º concluído às 12:00'}],floors:FLOOR_NUMBERS.map(makeFloor)}}
function migrate(v){if(!v)return fresh();if((v.version||1)<2){const seed=fresh();v.settings={...v.settings,unassignedAbsencesToday:1};v.today=seed.today;v.history=v.history||[];if(!v.history.some(h=>h.id==='afaq-10-20260818'))v.history.push({id:'afaq-10-20260818',service:'afaq',floor:10,date:BASE_DATE,time:'12:00',label:'AF/AQ 10º concluído às 12:00'});const af=v.floors?.find(f=>f.number===11)?.stages.find(s=>s.service==='afaq');if(af)af.status='in_progress';const esg=v.floors?.find(f=>f.number===12)?.stages.find(s=>s.service==='esgoto');if(esg)esg.status='in_progress';v.version=2}if((v.version||2)<3){const existing=new Map((v.floors||[]).map(f=>[f.number,f]));v.floors=FLOOR_NUMBERS.map(n=>existing.get(n)||makeFloor(n));v.project={...v.project,startFloor:-2,targetFloor:25};v.employees=(v.employees||[]).map(e=>({...e,frontKey:e.frontKey||''}));v.version=3}if((v.version||3)<4){const oldDay=v.today||seededDay();v.days=v.days||{[oldDay.date||BASE_DATE]:{...oldDay,note:oldDay.note||'',plans:oldDay.plans||[]}};Object.values(v.days).forEach(d=>{d.note=d.note||'';d.plans=d.plans||[];d.assignments=d.assignments||[];d.events=d.events||[]});v.checklistTemplates=v.checklistTemplates||defaultTemplates();v.version=4}if((v.version||4)<5){v.settings={...v.settings,defaultWorkStart:v.settings?.defaultWorkStart||'07:30'};Object.values(v.days||{}).forEach(d=>{d.sessions=d.sessions||[]});if(v.today)v.today.sessions=v.today.sessions||[];v.version=5}if((v.version||5)<6){Object.values(v.days||{}).forEach(d=>{d.rdoStatus=d.rdoStatus||'draft';d.rdoDraft=d.rdoDraft||null});if(v.today){v.today.rdoStatus=v.today.rdoStatus||'draft';v.today.rdoDraft=v.today.rdoDraft||null}v.version=6}return v}
const DB='fluxodre-campo-standalone';function openDb(){return new Promise((ok,no)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore('kv');r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}async function load(){try{const db=await openDb();const tx=db.transaction('kv','readonly'),r=tx.objectStore('kv').get('state');const v=await new Promise((ok,no)=>{r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)});return migrate(v||fresh())}catch{try{return migrate(JSON.parse(localStorage.getItem(DB)))}catch{return fresh()}}}async function save(){refreshRdoDrafts();try{const db=await openDb();const tx=db.transaction('kv','readwrite');tx.objectStore('kv').put(structuredClone(state),'state')}catch{localStorage.setItem(DB,JSON.stringify(state))}if(window.multiuserContext?.role==='admin'&&window.multiuserSync)window.multiuserSync(structuredClone(state))}
