function timeMinutes(v){if(!/^\d{2}:\d{2}$/.test(v||''))return null;const[h,m]=v.split(':').map(Number);return h*60+m}
function minuteTime(n){n=Math.max(0,Math.min(1439,Math.round(n)));return`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function safeActionTime(session){const last=session.segments?.[session.segments.length-1],base=last?.end||last?.start||state.settings.defaultWorkStart||'07:30',min=timeMinutes(base)||0,now=timeMinutes(nowTime())||0;return minuteTime(Math.max(now,min+(last?.end?1:0)))}
function employeeName(id){return state.employees.find(e=>e.id===id)?.name||id}
function linkedCrewIds(service,floor){const key=`${service}:${floor}`;return state.employees.filter(e=>e.frontKey===key).map(e=>e.id)}
function crewAt(session,time){const t=timeMinutes(time),events=[...(session.crewEvents||[])].sort((a,b)=>(timeMinutes(a.time)||0)-(timeMinutes(b.time)||0));let ids=events[0]?.employeeIds||[];for(const event of events){if((timeMinutes(event.time)||0)<=t)ids=event.employeeIds;else break}return ids}
function sessionMinutes(session){return(session.segments||[]).reduce((sum,seg)=>{const a=timeMinutes(seg.start),b=timeMinutes(seg.end);return sum+(a!==null&&b!==null&&b>=a?b-a:0)},0)}
function sessionManHours(session){let crewMinutes=0;for(const seg of session.segments||[]){const start=timeMinutes(seg.start),end=timeMinutes(seg.end);if(start===null||end===null||end<start)continue;const events=[...(session.crewEvents||[])].filter(e=>{const t=timeMinutes(e.time);return t!==null&&t>start&&t<end}).sort((a,b)=>timeMinutes(a.time)-timeMinutes(b.time));let cursor=start,ids=crewAt(session,seg.start);for(const event of events){const t=timeMinutes(event.time);crewMinutes+=(t-cursor)*ids.length;cursor=t;ids=event.employeeIds}crewMinutes+=(end-cursor)*ids.length}return crewMinutes/60}
function formatMinutes(n){const h=Math.floor(n/60),m=n%60;return`${h}h${String(m).padStart(2,'0')}`}
function sessionResultLabel(v){return{in_progress:'Continua em execução',inspection:'Verificação',completed:'Concluído',blocked:'Bloqueado',no_progress:'Sem avanço relevante'}[v]||'Sem resultado'}
function sessionStateLabel(v){return{running:'Em execução',paused:'Pausado',finished:'Sessão concluída'}[v]||v}
function sessionTone(v){return v==='finished'?'completed':v==='paused'?'released':'progress'}
function getSession(day,id){return(day.sessions||[]).find(s=>s.id===id)}
function allSessions(){return Object.values(state.days||{}).flatMap(d=>d.sessions||[])}
function productivityByService(){const groups={};for(const s of allSessions().filter(x=>x.state==='finished')){const g=groups[s.service]||(groups[s.service]={service:s.service,sessions:0,minutes:0,manHours:0,completed:0});g.sessions++;g.minutes+=sessionMinutes(s);g.manHours+=sessionManHours(s);if(s.result==='completed')g.completed++}return Object.values(groups)}function rdoDraftFor(day){const sessions=day.sessions||[],finished=sessions.filter(s=>s.state==='finished'),open=sessions.filter(s=>s.state!=='finished'),present=Number(day.presentCount||0),absent=Number(day.absentCount||0),attendanceMarked=present+absent,manHours=finished.reduce((sum,s)=>sum+sessionManHours(s),0),completed=finished.filter(s=>s.result==='completed').length,plans=day.plans||[],assignments=day.assignments||[],events=day.events||[],issues=(state.issues||[]).filter(i=>i.status==='open'),checks=[attendanceMarked>0,plans.length>0||assignments.length>0,finished.length>0,open.length===0],completeness=Math.round(checks.filter(Boolean).length/checks.length*100);return{date:day.date,presentCount:present,absentCount:absent,attendanceMarked,plansCount:plans.length,assignmentsCount:assignments.length,sessionsCount:sessions.length,finishedSessions:finished.length,openSessions:open.length,completedResults:completed,productiveMinutes:finished.reduce((sum,s)=>sum+sessionMinutes(s),0),manHours:Number(manHours.toFixed(2)),note:day.note||'',events:events.map(e=>({time:e.time,label:e.label})),openIssues:issues.map(i=>({id:i.id,title:i.title,type:i.type,floor:i.floor,service:i.service,external:!!i.external})),completeness,ready:attendanceMarked>0&&finished.length>0&&open.length===0,generatedAt:new Date().toISOString()}}function refreshRdoDrafts(){Object.values(state.days||{}).forEach(day=>{day.rdoDraft=rdoDraftFor(day);day.rdoStatus=day.rdoStatus||'draft'})}function rdoClosure(day){const d=rdoDraftFor(day),status=day.rdoStatus==='ready_for_desktop'?'Pronto para Desktop':d.ready?'Pronto para revisar':'Em preenchimento',tone=day.rdoStatus==='ready_for_desktop'?'completed':d.ready?'released':'progress';return`<section class="section"><div class="section-head"><div><h2>Fechamento do dia</h2><p>O RDO é montado automaticamente com presença, produção, eventos e pendências.</p></div></div><div class="card rdo-card"><div class="row"><div><strong>RDO automático</strong><div class="meta">${d.finishedSessions} apontamento(s) concluído(s) · ${d.manHours.toFixed(2)} HH · ${d.openSessions} em aberto</div></div><span class="badge ${tone}">${status}</span></div><div class="rdo-progress"><i style="width:${d.completeness}%"></i></div><div class="meta">${d.completeness}% dos dados operacionais essenciais disponíveis.</div><button id="reviewRdo" class="linkbtn small-btn">Revisar fechamento</button></div></section>`}function openRdoReview(){const day=getDay(selectedDate,true),d=rdoDraftFor(day),missing=[];if(!d.attendanceMarked)missing.push('presença/faltas');if(!d.finishedSessions)missing.push('apontamento de produção concluído');if(d.openSessions)missing.push(`${d.openSessions} apontamento(s) ainda aberto(s)`);sheet.innerHTML=`<div class="sheet"><div class="sheet-head"><div><h2>Fechamento · ${dateBR(day.date)}</h2><div class="meta">Prévia automática para o FLUXODRE Desktop.</div></div><button class="close">×</button></div><div class="metrics"><div class="metric"><span>Equipe</span><strong>${d.presentCount} / ${d.absentCount}</strong><div class="meta">presentes / faltas</div></div><div class="metric"><span>Homem-hora</span><strong>${d.manHours.toFixed(2)}</strong></div></div><div class="card"><strong>Produção</strong><div class="meta">${d.finishedSessions} sessão(ões) concluída(s) · ${d.completedResults} conclusão(ões) física(s)</div></div><div class="card"><strong>Ocorrências e pendências</strong><div class="meta">${d.events.length} movimentação(ões) · ${d.openIssues.length} pendência(s) aberta(s)</div>${day.note?`<p>${esc(day.note)}</p>`:''}</div>${missing.length?`<div class="card notice"><b>!</b><div><strong>Ainda falta conferir</strong><div class="meta">${missing.map(esc).join(' · ')}</div></div></div>`:'<div class="card notice"><b>✓</b><div><strong>Dados essenciais completos</strong><div class="meta">O Desktop pode consolidar o RDO e gerar o documento final.</div></div></div>'}<button id="prepareRdo" class="btn" style="width:100%">${d.ready?'Marcar pronto para Desktop':'Salvar rascunho para Desktop'}</button></div>`;sheet.showModal();sheet.querySelector('.close').addEventListener('click',()=>sheet.close());$('#prepareRdo').addEventListener('click',async()=>{day.rdoDraft=rdoDraftFor(day);day.rdoStatus=day.rdoDraft.ready?'ready_for_desktop':'draft';await save();sheet.close();renderDay();show(day.rdoStatus==='ready_for_desktop'?'RDO preparado para o Desktop.':'Rascunho do RDO salvo. Complete os itens pendentes.')})}
function sessionEmployeeMinutes(session){const totals={};for(const seg of session.segments||[]){const start=timeMinutes(seg.start),end=timeMinutes(seg.end);if(start===null||end===null||end<start)continue;const events=[...(session.crewEvents||[])].filter(e=>{const t=timeMinutes(e.time);return t!==null&&t>start&&t<end}).sort((a,b)=>timeMinutes(a.time)-timeMinutes(b.time));let cursor=start,ids=crewAt(session,seg.start);const add=(until)=>{for(const id of ids)totals[id]=(totals[id]||0)+(until-cursor);cursor=until};for(const event of events){const t=timeMinutes(event.time);add(t);ids=event.employeeIds}add(end)}return totals}function employeeStats(id,daysBack=30){const cutoff=shiftDate(localISODate(),-(daysBack-1));let minutes=0,sessions=0,completed=0;for(const s of allSessions().filter(x=>x.state==='finished'&&x.date>=cutoff)){const byEmployee=sessionEmployeeMinutes(s),worked=Number(byEmployee[id]||0);if(!worked)continue;minutes+=worked;sessions++;if(s.result==='completed')completed++}return{hours:minutes/60,sessions,completed}}function plannedActualByService(daysBack=7){const cutoff=shiftDate(localISODate(),-(daysBack-1)),rows={};for(const [date,day] of Object.entries(state.days||{})){if(date<cutoff||date>localISODate())continue;for(const p of day.plans||[]){const r=rows[p.service]||(rows[p.service]={service:p.service,planned:0,executed:0,finished:0,completed:0,manHours:0});r.planned++;if((day.sessions||[]).some(s=>s.state==='finished'&&s.service===p.service&&Number(s.floor)===Number(p.floor)))r.executed++}for(const s of day.sessions||[]){if(s.state!=='finished')continue;const r=rows[s.service]||(rows[s.service]={service:s.service,planned:0,executed:0,finished:0,completed:0,manHours:0});r.finished++;r.manHours+=sessionManHours(s);if(s.result==='completed')r.completed++}}return Object.values(rows)}function completionDate(service,floor){return(state.history||[]).filter(h=>h.service===service&&Number(h.floor)===Number(floor)&&h.date).map(h=>h.date).sort().at(-1)||null}function scheduleHealth(service){let onTime=0,late=0,overdue=0,due=0;for(const f of state.floors||[]){const st=f.stages?.find(s=>s.service===service);if(!st?.targetDate||f.number<0)continue;due++;if(st.status==='completed'){const done=completionDate(service,f.number);if(done&&done<=st.targetDate)onTime++;else if(done)late++}else if(st.targetDate<localISODate())overdue++}return{onTime,late,overdue,due}}function serviceForecast(group){if(!group?.completed||!group.manHours)return null;const open=(state.floors||[]).filter(f=>f.number>=0).filter(f=>{const s=f.stages?.find(x=>x.service===group.service);return s&&s.status!=='completed'&&s.status!=='blocked'}).length,activeCrew=Math.max(1,state.employees.filter(e=>String(e.frontKey||'').startsWith(`${group.service}:`)).length),mhPerCompletion=group.manHours/group.completed;return{open,activeCrew,mhPerCompletion,days:open*mhPerCompletion/(activeCrew*8)}}function employeeChecks(selected=[]){const set=new Set(selected);return`<div class="crew-grid">${state.employees.map(e=>`<label class="crew-choice"><input type="checkbox" value="${e.id}" ${set.has(e.id)?'checked':''}><span>${esc(e.name)}</span></label>`).join('')}</div>`}
function sessionCard(s){const minutes=sessionMinutes(s),crew=(s.crewEvents?.[0]?.employeeIds||[]).map(employeeName),changes=(s.crewEvents||[]).slice(1),range=(s.segments||[]).map(x=>`${x.start}–${x.end||'...'}`).join(' · ');return`<div class="card session-card" data-session="${s.id}"><div class="row"><div><div class="title">${esc(SERVICES[s.service]?.[0]||s.service)} · ${floorLabel(Number(s.floor))}</div><div class="meta">${range||'Sem horário'} · ${minutes?`${formatMinutes(minutes)} produtivas`:'em curso'}</div><div class="meta">Equipe inicial: ${crew.map(esc).join(', ')||'não informada'}${s.corrected?' · Horários corrigidos':''}</div>${changes.map(e=>`<div class="meta">Equipe atualizada ${esc(e.time)} · ${e.employeeIds.map(employeeName).map(esc).join(', ')||'sem equipe'}</div>`).join('')}${s.result?`<div class="meta">Resultado físico: ${sessionResultLabel(s.result)}${s.note?` · ${esc(s.note)}`:''}</div>`:''}</div><span class="badge ${sessionTone(s.state)}">${sessionStateLabel(s.state)}</span></div><div class="session-actions">${s.state==='running'?'<button class="linkbtn session-pause">Pausar</button>':''}${s.state==='paused'?'<button class="linkbtn session-resume">Retomar</button>':''}${s.state!=='finished'?'<button class="btn session-finish">Concluir</button><button class="linkbtn session-crew">Atualizar equipe</button>':''}<button class="linkbtn session-edit">Editar horários</button><button class="linkbtn session-details">Detalhes</button></div></div>`}
function bindSessionCards(){document.querySelectorAll('.session-card').forEach(card=>{const id=card.dataset.session;card.querySelector('.session-pause')?.addEventListener('click',()=>pauseSession(id));card.querySelector('.session-resume')?.addEventListener('click',()=>resumeSession(id));card.querySelector('.session-finish')?.addEventListener('click',()=>openFinishSession(id));card.querySelector('.session-crew')?.addEventListener('click',()=>openCrewUpdate(id));card.querySelector('.session-edit')?.addEventListener('click',()=>openEditTimes(id));card.querySelector('.session-details')?.addEventListener('click',()=>openSessionDetails(id))})}
function openNewSession(prefill={}){const service=prefill.service||'afaq',floor=Number(prefill.floor??11),linked=linkedCrewIds(service,floor),preset=linked.length?linked:(prefill.employeeIds||[]),start=prefill.start||state.settings.defaultWorkStart||'07:30';sheet.innerHTML=`<div class="sheet"><div class="sheet-head"><div><h2>Novo apontamento</h2><div class="meta">Registre o executado sem alterar automaticamente o avanço físico.</div></div><button class="close">×</button></div><div class="form"><label>Serviço<select id="sservice">${Object.entries(SERVICES).map(([k,v])=>`<option value="${k}" ${k===service?'selected':''}>${v[0]}</option>`).join('')}</select></label><label>Pavimento<select id="sfloor">${state.floors.filter(f=>f.number>=0).map(f=>`<option value="${f.number}" ${f.number===floor?'selected':''}>${floorLabel(f.number)}</option>`).join('')}</select></label><label>Início<div class="time-inline"><input id="sstart" type="time" value="${start}"><button type="button" id="startNow" class="linkbtn">Agora</button></div></label><div><div class="form-label">Funcionários</div><div id="sessionCrew">${employeeChecks(preset)}</div></div></div><button class="btn" id="createSession">Criar apontamento</button></div>`;sheet.showModal();sheet.querySelector('.close').addEventListener('click',()=>sheet.close());$('#startNow').addEventListener('click',()=>{$('#sstart').value=nowTime()});const syncCrew=()=>{const ids=linkedCrewIds($('#sservice').value,Number($('#sfloor').value));$('#sessionCrew').innerHTML=employeeChecks(ids)};$('#sservice').addEventListener('change',syncCrew);$('#sfloor').addEventListener('change',syncCrew);$('#createSession').addEventListener('click',async()=>{const ids=[...sheet.querySelectorAll('#sessionCrew input:checked')].map(i=>i.value),startValue=$('#sstart').value;if(!ids.length)return show('Selecione ao menos 1 funcionário.');if(timeMinutes(startValue)===null)return show('Informe um horário de início válido.');const d=getDay(selectedDate,true),session={id:crypto.randomUUID(),date:selectedDate,service:$('#sservice').value,floor:Number($('#sfloor').value),state:'running',segments:[{start:startValue,end:null}],crewEvents:[{time:startValue,employeeIds:ids}],result:null,note:'',corrected:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};d.sessions.push(session);await save();sheet.close();renderDay();show('Apontamento iniciado.')})}
async function pauseSession(id){const d=getDay(selectedDate,true),s=getSession(d,id),open=[...(s?.segments||[])].reverse().find(x=>!x.end);if(!s||s.state!=='running'||!open)return;open.end=safeActionTime(s);s.state='paused';s.updatedAt=new Date().toISOString();await save();renderDay();show('Apontamento pausado.')}
async function resumeSession(id){const d=getDay(selectedDate,true),s=getSession(d,id);if(!s||s.state!=='paused')return;const start=safeActionTime(s);s.segments.push({start,end:null});s.state='running';s.updatedAt=new Date().toISOString();await save();renderDay();show('Apontamento retomado.')}
function openFinishSession(id){const d=getDay(selectedDate,true),s=getSession(d,id);if(!s)return;const open=[...(s.segments||[])].reverse().find(x=>!x.end),endDefault=open?safeActionTime(s):(s.segments.at(-1)?.end||safeActionTime(s));sheet.innerHTML=`<div class="sheet"><div class="sheet-head"><div><h2>Concluir apontamento</h2><div class="meta">Tempo trabalhado e avanço físico são registrados separadamente.</div></div><button class="close">×</button></div><div class="form"><label>Fim<input id="send" type="time" value="${endDefault}"></label><label>Resultado físico<select id="sresult"><option value="in_progress">Continua em execução</option><option value="inspection">Verificação</option><option value="completed">Concluído</option><option value="blocked">Bloqueado</option><option value="no_progress">Sem avanço relevante</option></select></label><label>Observação<textarea id="snote" placeholder="Ex.: faltou material para finalizar"></textarea></label></div><button class="btn" id="finishSession">Salvar conclusão</button></div>`;sheet.showModal();sheet.querySelector('.close').addEventListener('click',()=>sheet.close());$('#finishSession').addEventListener('click',async()=>{const end=$('#send').value;if(open){const a=timeMinutes(open.start),b=timeMinutes(end);if(a===null||b===null||b<a)return show('Horário de fim inválido.');open.end=end}const result=$('#sresult').value;s.state='finished';s.result=result;s.note=$('#snote').value.trim();s.updatedAt=new Date().toISOString();const stage=state.floors.find(f=>f.number===s.floor)?.stages.find(x=>x.service===s.service);let moved=null;if(result==='completed')moved=advanceFront(s.service,s.floor,s.date);else if(stage&&result!=='no_progress'){stage.status=result;upsertDayAssignment(s.date,s.service,s.floor,result,s.note,crewAt(s,end).length)}const movement=moved?` · ${floorLabel(moved.nextFloor)} aberto automaticamente`:'';d.events.push({id:`session-${s.id}`,time:end,label:`${SERVICES[s.service][0]} ${floorLabel(s.floor)}: ${sessionResultLabel(result)}${movement}`});state.history.push({id:`session-${s.id}`,service:s.service,floor:s.floor,date:s.date,time:end,label:`${SERVICES[s.service][0]} ${floorLabel(s.floor)}: ${sessionResultLabel(result)}${movement}`});await save();sheet.close();renderDay();show(moved?`Apontamento concluído. ${floorLabel(moved.nextFloor)} aberto automaticamente.`:'Apontamento concluído.')})}
function openCrewUpdate(id){const d=getDay(selectedDate,true),s=getSession(d,id);if(!s)return;const time=safeActionTime(s),current=crewAt(s,time);sheet.innerHTML=`<div class="sheet"><div class="sheet-head"><div><h2>Atualizar equipe</h2><div class="meta">A equipe anterior permanece no histórico.</div></div><button class="close">×</button></div><div class="form"><label>Horário<input id="crewTime" type="time" value="${time}"></label><div><div class="form-label">Funcionários a partir deste horário</div><div id="crewUpdateList">${employeeChecks(current)}</div></div></div><button class="btn" id="saveCrewUpdate">Salvar equipe</button></div>`;sheet.showModal();sheet.querySelector('.close').addEventListener('click',()=>sheet.close());$('#saveCrewUpdate').addEventListener('click',async()=>{const ids=[...sheet.querySelectorAll('#crewUpdateList input:checked')].map(i=>i.value),t=$('#crewTime').value;if(!ids.length)return show('Selecione ao menos 1 funcionário.');if(timeMinutes(t)===null)return show('Informe um horário válido.');s.crewEvents.push({time:t,employeeIds:ids});s.crewEvents.sort((a,b)=>timeMinutes(a.time)-timeMinutes(b.time));s.updatedAt=new Date().toISOString();await save();sheet.close();renderDay();show('Equipe da sessão atualizada.')})}
function openEditTimes(id){const d=getDay(selectedDate,true),s=getSession(d,id);if(!s)return;sheet.innerHTML=`<div class="sheet"><div class="sheet-head"><div><h2>Editar horários</h2><div class="meta">A alteração ficará marcada como correção manual.</div></div><button class="close">×</button></div><div id="segmentEditor">${(s.segments||[]).map((seg,i)=>`<div class="segment-row" data-index="${i}"><label>Início<input class="seg-start" type="time" value="${seg.start}"></label><label>Fim<input class="seg-end" type="time" value="${seg.end||''}"></label></div>`).join('')}</div><button class="linkbtn" id="addSegment">+ Adicionar período</button><button class="btn" id="saveTimes">Salvar horários</button></div>`;sheet.showModal();sheet.querySelector('.close').addEventListener('click',()=>sheet.close());$('#addSegment').addEventListener('click',()=>{$('#segmentEditor').insertAdjacentHTML('beforeend','<div class="segment-row"><label>Início<input class="seg-start" type="time"></label><label>Fim<input class="seg-end" type="time"></label></div>')});$('#saveTimes').addEventListener('click',async()=>{const segments=[...sheet.querySelectorAll('.segment-row')].map(r=>({start:r.querySelector('.seg-start').value,end:r.querySelector('.seg-end').value||null}));let prevEnd=null;for(const seg of segments){const a=timeMinutes(seg.start),b=seg.end?timeMinutes(seg.end):null;if(a===null||b===null||b<a||(prevEnd!==null&&a<prevEnd))return show('Revise a ordem dos horários.');prevEnd=b}s.segments=segments;s.corrected=true;if(s.state==='running'&&!segments.some(x=>!x.end))s.state='paused';s.updatedAt=new Date().toISOString();await save();sheet.close();renderDay();show('Horários corrigidos.')})}
function openSessionDetails(id){const d=getDay(selectedDate,false),s=getSession(d,id);if(!s)return;const minutes=sessionMinutes(s),man=sessionManHours(s),events=(s.crewEvents||[]).map((e,i)=>`<div class="timeline-item"><strong>${i?'Equipe atualizada':'Equipe inicial'} · ${esc(e.time)}</strong><div class="meta">${e.employeeIds.map(employeeName).map(esc).join(', ')}</div></div>`).join('');sheet.innerHTML=`<div class="sheet"><div class="sheet-head"><div><h2>${SERVICES[s.service][0]} · ${floorLabel(s.floor)}</h2><div class="meta">${dateBR(s.date)}</div></div><button class="close">×</button></div><div class="metrics"><div class="metric"><span>Tempo produtivo</span><strong>${formatMinutes(minutes)}</strong></div><div class="metric"><span>Homem-hora</span><strong>${man.toFixed(2)}</strong></div></div><div class="session-timeline">${events}</div>${s.corrected?'<div class="card notice"><b>i</b><div><strong>Horários corrigidos</strong><div class="meta">Existe ajuste manual neste apontamento.</div></div></div>':''}${s.result?`<div class="card"><strong>Resultado físico</strong><div class="meta">${sessionResultLabel(s.result)}</div></div>`:''}</div>`;sheet.showModal();sheet.querySelector('.close').addEventListener('click',()=>sheet.close())}
function renderDateNav(){return`<div class="date-nav"><button id="prevDay" aria-label="Dia anterior">‹</button><input id="dayPicker" type="date" value="${selectedDate}"><button id="nextDay" aria-label="Próximo dia">›</button><button id="todayBtn" class="today-btn">Hoje</button></div>`}
function bindDateNav(){$('#prevDay').addEventListener('click',()=>{selectedDate=shiftDate(selectedDate,-1);renderDay()});$('#nextDay').addEventListener('click',()=>{selectedDate=shiftDate(selectedDate,1);renderDay()});$('#dayPicker').addEventListener('change',e=>{if(e.target.value){selectedDate=e.target.value;renderDay()}});$('#todayBtn').addEventListener('click',()=>{selectedDate=localISODate();renderDay()})}
function renderDay(){const day=ensureDayContinuity(selectedDate),assignments=day.assignments||[],sessions=day.sessions||[],active=assignments.filter(a=>isActiveAssignment(a)),isSeed=day.date===BASE_DATE,kind=selectedDate===localISODate()?'Hoje':selectedDate<localISODate()?'Histórico':'Planejamento';content.innerHTML=`${renderDateNav()}<section class="hero"><small>${kind} · ${esc(state.project?.name||'Obra')}</small><div class="date">${dateTitle(selectedDate)}</div><div class="stats"><div class="stat"><strong>${day.presentCount??'—'}</strong><span>presentes</span></div><div class="stat"><strong>${day.absentCount??'—'}</strong><span>faltas</span></div><div class="stat"><strong>${sessions.filter(s=>s.state==='running'||s.state==='paused').length||active.length}</strong><span>frentes ativas</span></div></div></section><div class="quick-actions"><button type="button" class="quick-action" data-screen="team"><strong>Equipe</strong><span>Vincular funcionários às frentes</span></button><button type="button" class="quick-action" data-screen="issues"><strong>Pendências</strong><span>Qualidade e bloqueios</span></button><button type="button" class="quick-action" data-screen="more"><strong>Planejamento</strong><span>Produtividade e previsão</span></button><button type="button" class="quick-action" data-screen="settings"><strong>Configurações</strong><span>Checklists e horários</span></button></div><section class="section"><div class="section-head"><div><h2>Nota do dia</h2><p>Use para registrar ocorrências, decisões ou lembretes desta data.</p></div></div><div class="card"><textarea id="dayNote" class="day-note" placeholder="Escreva uma nota para ${dateBR(selectedDate)}">${esc(day.note||'')}</textarea><button id="saveDayNote" class="btn small-btn">Salvar nota</button></div></section><section class="section"><div class="section-head"><div><h2>Planejamento do dia</h2><p>O que deveria acontecer em ${dateBR(selectedDate)}.</p></div><button id="newPlan" class="linkbtn">+ Planejar</button></div>${(day.plans||[]).map(planCard).join('')||'<div class="empty card">Nenhum planejamento cadastrado para esta data.</div>'}</section><section class="section"><div class="section-head"><div><h2>Apontamentos de produção</h2><p>Executado: tempo, equipe e resultado físico ficam separados.</p></div><button id="newSession" class="btn">+ Apontar</button></div>${sessions.map(sessionCard).join('')||'<div class="empty card">Nenhum apontamento real nesta data.</div>'}</section>${assignments.length?`<section class="section"><div class="section-head"><div><h2>Produção registrada anteriormente</h2><p>${isSeed?'Registro legado preservado; o status real do pavimento prevalece.':'Histórico anterior desta data.'}</p></div></div>${assignments.map(a=>workCard(a,day.date)).join('')}</section>`:''}${(day.events||[]).length?`<section class="section"><div class="section-head"><div><h2>Movimentações</h2><p>Eventos registrados nesta data.</p></div></div>${day.events.map(e=>`<div class="card"><strong>${esc(e.time)}</strong><div class="meta">${esc(e.label)}</div></div>`).join('')}</section>`:''}${selectedDate===BASE_DATE?`<section class="section"><div class="section-head"><div><h2>Atenção</h2><p>Itens que afetam a escala.</p></div></div><div class="card notice"><b>!</b><div><strong>1 falta registrada</strong><div class="meta">O nome do funcionário ausente ainda não foi informado.</div></div></div><div class="card notice"><b>↯</b><div><strong>Dreno bloqueado externamente</strong><div class="meta">Aguardando liberação da construtora; não conta como atraso da equipe.</div></div></div></section>`:''}${selectedDate<=localISODate()?rdoClosure(day):''}`;bindDateNav();bindStages();bindSessionCards();$('#reviewRdo')?.addEventListener('click',openRdoReview);$('#saveDayNote').addEventListener('click',async()=>{const d=getDay(selectedDate,true);d.note=$('#dayNote').value.trim();await save();show('Nota do dia salva.')});$('#newPlan').addEventListener('click',openPlan);$('#newSession').addEventListener('click',()=>openNewSession());document.querySelectorAll('.plan-delete').forEach(b=>b.addEventListener('click',async()=>{const d=getDay(selectedDate,true);d.plans=d.plans.filter(p=>p.id!==b.dataset.id);await save();renderDay();show('Planejamento removido.')}));document.querySelectorAll('.plan-start').forEach(b=>b.addEventListener('click',()=>{const d=getDay(selectedDate,false),p=(d.plans||[]).find(x=>x.id===b.dataset.id);if(p)openNewSession({service:p.service,floor:p.floor})}))}
function planCard(p){return`<div class="card plan-card"><div><strong>${esc(SERVICES[p.service]?.[0]||p.service)} · ${floorLabel(Number(p.floor))}</strong><div class="meta">${p.crew} ${Number(p.crew)===1?'pessoa':'pessoas'}${p.note?` · ${esc(p.note)}`:''}</div></div><div class="plan-actions"><button class="linkbtn plan-start" data-id="${p.id}">Iniciar</button><button class="plan-delete" data-id="${p.id}" aria-label="Remover planejamento">×</button></div></div>`}
function openPlan(){sheet.innerHTML=`<div class="sheet"><div class="sheet-head"><div><h2>Planejar ${dateBR(selectedDate)}</h2><div class="meta">Defina a frente prevista para este dia.</div></div><button class="close">×</button></div><div class="form"><label>Serviço<select id="pservice">${Object.entries(SERVICES).map(([k,v])=>`<option value="${k}">${v[0]}</option>`).join('')}</select></label><label>Pavimento<select id="pfloor">${state.floors.map(f=>`<option value="${f.number}">${floorLabel(f.number)}</option>`).join('')}</select></label><label>Pessoas<input id="pcrew" type="number" min="1" max="30" value="1"></label><label>Início<input id="pstart" type="time" value="${state.settings.defaultWorkStart||'07:30'}"></label><div><div class="form-label">Funcionários atribuídos</div><div id="planEmployees">${employeeChecks()}</div></div><label>Observação<textarea id="pnote" placeholder="Ex.: continuar distribuição"></textarea></label></div><button class="btn" id="savePlan">Salvar planejamento</button></div>`;sheet.showModal();sheet.querySelector('.close').addEventListener('click',()=>sheet.close());$('#savePlan').addEventListener('click',async()=>{const crew=Math.max(1,Number($('#pcrew').value)||1),d=getDay(selectedDate,true);d.plans.push({id:crypto.randomUUID(),service:$('#pservice').value,floor:Number($('#pfloor').value),crew,startTime:$('#pstart').value||state.settings.defaultWorkStart||'07:30',employeeIds:[...sheet.querySelectorAll('#planEmployees input:checked')].map(i=>i.value),note:$('#pnote').value.trim()});await save();sheet.close();renderDay();show('Planejamento salvo.')})}
function workCard(s,date=BASE_DATE){const linked=state.floors.some(f=>f.number===s.floor),status=assignmentStatus(s,date),count=linkedCount(s.service,s.floor);let tag='Trabalhado',tone='progress';if(status==='completed'){tag='Concluído';tone='completed'}else if(status==='in_progress'){tag='Em execução';tone='progress'}else if(status==='released'){tag='Liberado';tone='released'}const body=`<div class="row"><div><div class="title">${esc(s.label)} · ${floorLabel(s.floor)}</div><div class="meta">${s.crew} ${s.crew===1?'pessoa':'pessoas'} · ${esc(s.note||'')}</div><div class="meta">${count} funcionário(s) vinculados nominalmente</div></div><span class="badge ${tone}">${tag}</span></div>`;return linked?`<button class="card work stage-open" data-floor="${s.floor}" data-service="${s.service}">${body}</button>`:`<div class="card work">${body}</div>`}
function renderFloors(){content.innerHTML=`<div class="section-head"><div><h2>Pavimentos</h2><p>Mapa da obra: ${floorLabel(Number(state.project?.startFloor??0))} ao ${floorLabel(Number(state.project?.targetFloor??1))}.</p></div></div><div class="grid">${state.floors.map(f=>`<div class="card floor" data-floor="${f.number}"><div class="row"><strong>${floorLabel(f.number)}</strong><span>${f.number<0?'Não liberado':`${progress(f)}%`}</span></div><div class="bar"><span style="width:${f.number<0?0:progress(f)}%"></span></div></div>`).join('')}</div>`;document.querySelectorAll('.floor').forEach(el=>el.addEventListener('click',()=>{selectedFloor=Number(el.dataset.floor);renderFloor()}))}
function renderFloor(){const f=state.floors.find(x=>x.number===selectedFloor);content.innerHTML=`<button class="back" id="back">← Pavimentos</button><div class="section-head"><div><h2>${floorLabel(f.number)}</h2><p>${f.number<0?'Pavimento não liberado.':'Etapas, situação e metas da obra.'}</p></div></div><div class="stage-list">${f.stages.map(s=>{const[tag,tone]=metaTag(s);return`<button class="stage stage-open" data-floor="${f.number}" data-service="${s.service}"><div><strong>${s.label}</strong><div class="meta">${f.number<0?'Pavimento não liberado':s.targetDate?`Meta ${dateBR(s.targetDate)}`:'Sem meta cadastrada'}</div></div><span class="badge ${tone}">${tag}</span></button>`}).join('')}</div>`;$('#back').addEventListener('click',()=>{selectedFloor=null;renderFloors()});bindStages()}
function bindStages(){document.querySelectorAll('.stage-open').forEach(b=>b.addEventListener('click',()=>openStage(Number(b.dataset.floor),b.dataset.service)))}
function openStage(floor,service){const f=state.floors.find(x=>x.number===floor),st=f.stages.find(x=>x.service===service),[tag,tone]=metaTag(st);if(floor<0){sheet.innerHTML=`<div class="sheet"><div class="sheet-head"><div><h2>${st.label} · ${floorLabel(floor)}</h2><div class="meta">Pavimento não liberado</div></div><button class="close">×</button></div><p><span class="badge ${tone}">${tag}</span></p><div class="card notice"><b>↯</b><div><strong>Frente indisponível</strong><div class="meta">Este pavimento ainda não foi liberado para execução.</div></div></div></div>`;sheet.showModal();sheet.querySelector('.close').addEventListener('click',()=>sheet.close());return}sheet.innerHTML=`<div class="sheet"><div class="sheet-head"><div><h2>${st.label} · ${floorLabel(floor)}</h2><div class="meta">${st.targetDate?`Meta da obra: ${dateBR(st.targetDate)}`:'Sem meta cadastrada'}</div></div><button class="close">×</button></div><p><span class="badge ${tone}">${tag}</span></p><div>${st.checklist.map(i=>`<label class="check"><input type="checkbox" data-id="${i.id}" ${i.checked?'checked':''}><span>${esc(i.label)}${i.required?' *':''}</span></label>`).join('')}</div><div style="margin-top:16px"><button class="btn" id="complete">Concluir etapa</button></div></div>`;sheet.showModal();sheet.querySelector('.close').addEventListener('click',()=>sheet.close());sheet.querySelectorAll('input[type=checkbox]').forEach(i=>i.addEventListener('change',async()=>{st.checklist.find(x=>x.id===i.dataset.id).checked=i.checked;await save()}));$('#complete').addEventListener('click',async()=>{const missing=st.checklist.filter(i=>i.required&&!i.checked);if(missing.length)return show(`Faltam ${missing.length} item(ns) do checklist.`);if(st.status==='completed')return show('Esta etapa já está concluída.');const moved=advanceFront(service,floor,selectedDate),time=nowTime(),d=getDay(selectedDate,true),label=moved?`${st.label} ${floorLabel(floor)} concluído · ${floorLabel(moved.nextFloor)} aberto automaticamente`:`${st.label} ${floorLabel(floor)} concluído`;d.events.push({id:crypto.randomUUID(),time,label});state.history.push({id:crypto.randomUUID(),service,floor,date:selectedDate,time,label});await save();sheet.close();render();show(moved?(moved.crewCount?`${st.label} do ${floorLabel(floor)} concluído. ${floorLabel(moved.nextFloor)} aberto com ${moved.crewCount} funcionário(s).`:`${st.label} do ${floorLabel(floor)} concluído. ${floorLabel(moved.nextFloor)} liberado automaticamente.`):`${st.label} do ${floorLabel(floor)} concluído.`)})}
function renderTeam(){const date=localISODate(),day=ensureDayContinuity(date),saturday=state.employees.filter(e=>e.compensationDays>0),options=frontOptions();content.innerHTML=`<div class="section-head"><div><h2>Equipe</h2><p>${state.employees.length} cadastrado(s) · referência ${dateBR(day.date)}: ${day.presentCount??0} presentes e ${day.absentCount??0} falta(s).</p></div></div><div class="card"><strong>Vinculação por frente</strong><div class="meta">Selecione a frente de cada funcionário. A alteração fica salva e sincronizada com a obra.</div></div>${state.employees.map((e,i)=>{const att=attendanceStatus(e,day);return`<div class="card employee"><div class="avatar">${i+1}</div><div class="employee-main"><strong>${e.name}</strong><small>${e.compensationDays} dia(s) a compensar${(()=>{const st=employeeStats(e.id);return st.sessions?` · ${st.hours.toFixed(1)} HH/30d · ${st.sessions} sessão(ões)`:''})()}</small><label class="front-label">Frente<select class="front-select" data-id="${e.id}"><option value="">Sem frente</option>${options.map(o=>`<option value="${o.key}" ${e.frontKey===o.key?'selected':''}>${o.label} · ${floorLabel(o.floor)}</option>`).join('')}</select></label></div><button class="att ${att}" data-id="${e.id}">${att==='absent'?'Faltou':att==='present'?'Presente':'Não registrado'}</button></div>`}).join('')}<section class="section"><div class="section-head"><div><h2>Próximo sábado</h2><p>Quem faltou paga o dia.</p></div></div><div class="card"><strong>${saturday.length} funcionário(s) com saldo nominal</strong><div class="meta">${saturday.map(e=>e.name).join(' · ')||'Nenhum nome associado ainda.'}</div><div class="meta">Além disso, ${state.settings.unassignedCompensationDays} dia(s) estão sem funcionário definido.</div><button id="compensate" class="linkbtn" style="margin-top:12px">Compensar 2 primeiros</button></div></section>`;document.querySelectorAll('.front-select').forEach(sel=>sel.addEventListener('change',async()=>{const e=state.employees.find(x=>x.id===sel.dataset.id),before=e.frontKey;e.frontKey=sel.value;if(sel.value){const[service,floorText]=sel.value.split(':'),floor=Number(floorText),stage=state.floors.find(f=>f.number===floor)?.stages.find(s=>s.service===service);if(stage&&stage.status==='not_started')stage.status='released';upsertDayAssignment(date,service,floor,stage?.status||'released','Equipe vinculada à frente',linkedCount(service,floor))}if(before&&before!==sel.value){const[oldService,oldFloorText]=before.split(':'),oldFloor=Number(oldFloorText),oldAssignment=getDay(date,true).assignments.find(a=>assignmentKey(a)===`${oldService}:${oldFloor}`);if(oldAssignment&&linkedCount(oldService,oldFloor)===0)oldAssignment.crew=0}await save();show(e.frontKey?'Frente vinculada.':'Funcionário sem frente.')}));document.querySelectorAll('.att').forEach(b=>b.addEventListener('click',async()=>{const d=getDay(date,true),e=state.employees.find(x=>x.id===b.dataset.id),was=attendanceStatus(e,d),next=was==='unmarked'?'present':was==='present'?'absent':'present';if(window.multiuserAttendance){try{const result=await window.multiuserAttendance(e.id,next);Object.assign(e,result.employee);Object.assign(d,result.day);d.attendance=d.attendance||{};await save();renderTeam()}catch{show('Não foi possível sincronizar a presença.')}}else{d.attendance=d.attendance||{};d.attendance[e.id]=next;d.presentCount=Object.values(d.attendance).filter(v=>v==='present').length;d.absentCount=Object.values(d.attendance).filter(v=>v==='absent').length;e.attendance=next;if(next==='absent'&&was!=='absent')e.compensationDays+=1;if(was==='absent'&&next!=='absent')e.compensationDays=Math.max(0,e.compensationDays-1);await save();renderTeam()}}));$('#compensate').addEventListener('click',async()=>{const list=state.employees.filter(e=>e.compensationDays>0).slice(0,2);if(!list.length)return show('Nenhum saldo nominal para compensar.');list.forEach(e=>e.compensationDays=Math.max(0,e.compensationDays-1));await save();renderTeam();show('Compensação registrada.')})}
function renderIssues(){const open=state.issues.filter(i=>i.status==='open');content.innerHTML=`<div class="section-head"><div><h2>Pendências</h2><p>Qualidade e bloqueios.</p></div><button class="linkbtn" id="newIssue">+ Nova</button></div>${open.map(i=>`<div class="card"><div class="row"><strong>${esc(i.title)}</strong><span class="badge ${i.type==='blocked'?'blocked':'progress'}">${i.type==='blocked'?'Bloqueio':'Pendência'}</span></div><div class="meta">${floorLabel(i.floor)} · ${SERVICES[i.service][0]}${i.external?' · responsabilidade externa':''}</div><p>${esc(i.reason||'')}</p></div>`).join('')||'<div class="empty">Nenhuma pendência aberta.</div>'}`;$('#newIssue').addEventListener('click',openIssue)}
function openIssue(){sheet.innerHTML=`<div class="sheet"><div class="sheet-head"><div><h2>Nova pendência</h2><div class="meta">Registre o problema no contexto da obra.</div></div><button class="close">×</button></div><div class="form"><label>Tipo<select id="itype"><option value="quality">Pendência de qualidade</option><option value="blocked">Bloqueio</option></select></label><label>Pavimento<select id="ifloor">${state.floors.map(f=>`<option value="${f.number}">${floorLabel(f.number)}</option>`).join('')}</select></label><label>Serviço<select id="iservice">${Object.entries(SERVICES).map(([k,v])=>`<option value="${k}">${v[0]}</option>`).join('')}</select></label><label>Título<input id="ititle" placeholder="Ex.: ponto fora de posição"></label><label>Descrição<textarea id="ireason"></textarea></label></div><button class="btn" id="saveIssue">Salvar pendência</button></div>`;sheet.showModal();sheet.querySelector('.close').addEventListener('click',()=>sheet.close());$('#saveIssue').addEventListener('click',async()=>{const title=$('#ititle').value.trim();if(!title)return show('Informe um título.');state.issues.push({id:crypto.randomUUID(),type:$('#itype').value,title,floor:Number($('#ifloor').value),service:$('#iservice').value,reason:$('#ireason').value.trim(),external:false,status:'open'});await save();sheet.close();renderIssues();show('Pendência registrada.')})}
function renderSettings(){const tpl=state.checklistTemplates[selectedChecklistService]||[];content.innerHTML=`<button class="back" data-screen="today">← Dias</button><div class="section-head"><div><h2>Configurações</h2><p>Administre parâmetros operacionais e modelos das frentes.</p></div></div><section class="card settings-card"><div class="section-head"><div><strong>Jornada</strong><p>O horário é apenas uma sugestão para novos apontamentos e pode ser corrigido depois.</p></div></div><label class="config-label">Horário padrão de início<input id="defaultStart" type="time" value="${esc(state.settings.defaultWorkStart||'07:30')}"></label><button id="saveDefaultStart" class="btn small-btn">Salvar horário</button></section><section class="card settings-card"><div class="section-head"><div><strong>Checklists por frente</strong><p>Alterações são aplicadas apenas às etapas ainda não concluídas. Etapas concluídas preservam o histórico.</p></div></div><label class="config-label">Frente<select id="checkService">${Object.entries(SERVICES).map(([k,v])=>`<option value="${k}" ${k===selectedChecklistService?'selected':''}>${v[0]}</option>`).join('')}</select></label><div id="checkAdmin" class="check-admin">${tpl.map(adminRow).join('')}</div><div class="settings-actions"><button id="addCheckItem" class="linkbtn">+ Adicionar item</button><button id="saveCheckModel" class="btn">Salvar modelo</button></div></section>`;$('#saveDefaultStart').addEventListener('click',async()=>{const v=$('#defaultStart').value;if(timeMinutes(v)===null)return show('Informe um horário válido.');state.settings.defaultWorkStart=v;await save();show('Horário padrão salvo.')});$('#checkService').addEventListener('change',e=>{selectedChecklistService=e.target.value;renderSettings()});$('#addCheckItem').addEventListener('click',()=>{$('#checkAdmin').insertAdjacentHTML('beforeend',adminRow({id:`tmp-${crypto.randomUUID()}`,label:'',required:true}));bindAdminRows();const inputs=document.querySelectorAll('.check-label-input');inputs[inputs.length-1]?.focus()});$('#saveCheckModel').addEventListener('click',saveChecklistModel);bindAdminRows()}
function adminRow(i){return`<div class="check-admin-row" data-id="${esc(i.id)}"><input class="check-label-input" value="${esc(i.label)}" placeholder="Item do checklist"><label class="required-toggle"><input class="check-required" type="checkbox" ${i.required?'checked':''}>Obrigatório</label><button class="remove-check" type="button" aria-label="Remover item">×</button></div>`}
function bindAdminRows(){document.querySelectorAll('.remove-check').forEach(b=>{b.onclick=()=>b.closest('.check-admin-row').remove()})}
async function saveChecklistModel(){const rows=[...document.querySelectorAll('.check-admin-row')],items=rows.map((r,i)=>({id:r.dataset.id.startsWith('tmp-')?`${selectedChecklistService}-${crypto.randomUUID()}`:r.dataset.id||`${selectedChecklistService}-${i}`,label:r.querySelector('.check-label-input').value.trim(),required:r.querySelector('.check-required').checked})).filter(i=>i.label);state.checklistTemplates[selectedChecklistService]=items;state.floors.forEach(f=>{const st=f.stages.find(s=>s.service===selectedChecklistService);if(!st||st.status==='completed')return;const old=st.checklist||[];st.checklist=items.map(item=>{const prev=old.find(x=>x.id===item.id)||old.find(x=>x.label===item.label);return{...item,checked:prev?.checked||false}})});await save();renderSettings();show('Modelo salvo e aplicado às etapas abertas.')}
function days(baseCrew,baseDays,actual,eff=.7){const effective=actual<=baseCrew?actual:baseCrew+(actual-baseCrew)*eff;return baseDays*baseCrew/effective}
function renderMore(){const productivity=productivityByService(),compare=plannedActualByService(),today=getDay(localISODate(),false),todayPlanned=(today.plans||[]).length,todayFinished=(today.sessions||[]).filter(s=>s.state==='finished').length,weekPlanned=compare.reduce((n,r)=>n+r.planned,0),weekExecuted=compare.reduce((n,r)=>n+r.executed,0),weekPct=weekPlanned?Math.round(weekExecuted/weekPlanned*100):0;content.innerHTML=`<div class="section-head"><div><h2>Planejamento</h2><p>Previsto × realizado, produtividade e tendência a partir dos apontamentos reais.</p></div></div><div class="metrics planning-top"><div class="metric"><span>Planejado hoje</span><strong>${todayPlanned}</strong></div><div class="metric"><span>Executado hoje</span><strong>${todayFinished}</strong></div><div class="metric"><span>Aderência 7 dias</span><strong>${weekPlanned?`${weekPct}%`:'—'}</strong></div><div class="metric"><span>Faltas médias/semana</span><strong>${Number(state.settings.averageWeeklyAbsences||0)}</strong></div></div><section class="section"><div class="section-head"><div><h2>Previsto × realizado · 7 dias</h2><p>Um planejamento conta como realizado quando existe sessão concluída da mesma frente e pavimento.</p></div></div>${compare.length?compare.map(r=>{const pct=r.planned?Math.round(r.executed/r.planned*100):null,tone=pct===null?'':pct>=90?'completed':pct>=70?'released':'overdue';return`<div class="card comparison-card"><div class="row"><div><strong>${esc(SERVICES[r.service]?.[0]||r.service)}</strong><div class="meta">${r.planned} planejado(s) · ${r.executed} executado(s) · ${r.completed} conclusão(ões)</div></div><span class="badge ${tone}">${pct===null?'Sem meta':`${pct}%`}</span></div><div class="comparison-bar"><i style="width:${Math.min(100,pct||0)}%"></i></div><div class="meta">${r.manHours.toFixed(1)} HH no período</div></div>`}).join(''):'<div class="empty card">Cadastre planejamentos e finalize sessões para formar a comparação.</div>'}</section><section class="section"><div class="section-head"><div><h2>Produtividade real</h2><p>Histórico acumulado das sessões encerradas.</p></div></div>${productivity.length?productivity.map(g=>{const health=scheduleHealth(g.service),forecast=serviceForecast(g);return`<div class="card productivity-card"><div class="row"><strong>${SERVICES[g.service]?.[0]||g.service}</strong><span class="badge completed">${g.sessions} sessão(ões)</span></div><div class="metrics compact-metrics"><div class="metric"><span>Horas produtivas</span><strong>${(g.minutes/60).toFixed(1)}h</strong></div><div class="metric"><span>Homem-hora</span><strong>${g.manHours.toFixed(1)}</strong></div></div><div class="meta">Conclusões físicas: ${g.completed}${g.completed?` · ${g.manHours/g.completed>=0?(g.manHours/g.completed).toFixed(1):'—'} HH/conclusão`:''}</div><div class="productivity-signals"><span>${health.overdue} meta(s) vencida(s)</span><span>${health.onTime} no prazo</span><span>${health.late} concluída(s) após meta</span></div>${forecast?`<div class="forecast"><b>Projeção operacional</b><span>${forecast.open} etapa(s) abertas · equipe atual ${forecast.activeCrew} · ~${forecast.days.toFixed(1)} dia(s) úteis no ritmo histórico</span></div>`:''}</div>`}).join(''):'<div class="empty card">Ainda não há sessões concluídas suficientes para produtividade real.</div>'}</section><section class="section card"><strong>Simulador de equipe · AF/AQ</strong><div class="meta">Base teórica atual: 4 pessoas · 5 dias/pavimento. O simulador não altera o planejamento salvo.</div><input class="range" id="crew" type="range" min="4" max="8" value="6"><div class="metrics" style="margin-top:12px"><div class="metric"><span>Equipe</span><strong id="crewVal">6</strong></div><div class="metric"><span>Ciclo estimado</span><strong id="cycle"></strong></div></div></section><button type="button" class="quick-action single-action" data-screen="settings"><strong>Configurações</strong><span>Horário padrão e checklists das frentes</span></button><section class="section card"><strong>Instalar no iPhone</strong><p class="meta">Abra no Safari → Compartilhar → Adicionar à Tela de Início. O app abre em modo standalone e guarda os dados deste aparelho.</p></section>`;const r=$('#crew'),update=()=>{$('#crewVal').textContent=r.value;$('#cycle').textContent=`${days(4,5,Number(r.value)).toFixed(2)} d`};r?.addEventListener('input',update);if(r)update()}
function bridgeLabel(entity){return({frentes_obra:'Frente',tarefas_obra:'Tarefa',rdos:'RDO',cronograma_etapas:'Planejamento'})[entity]||entity}function bridgeTitle(item){const p=item?.payload||{};if(item.entity==='frentes_obra')return p.nome||`Frente #${item.localId}`;if(item.entity==='tarefas_obra')return p.titulo||`Tarefa #${item.localId}`;if(item.entity==='rdos')return `RDO ${p.data||`#${item.localId}`}`;if(item.entity==='cronograma_etapas')return p.nome||`Etapa #${item.localId}`;return`#${item.localId}`}function bridgeMeta(item){const p=item?.payload||{};if(item.entity==='tarefas_obra')return`${p.status||'aberta'}${p.prazo?` · prazo ${dateBR(p.prazo)}`:''}`;if(item.entity==='frentes_obra')return String(p.status||'ativa');if(item.entity==='rdos')return String(p.status||'rascunho');if(item.entity==='cronograma_etapas')return`${p.status||'pendente'} · ${Number(p.percentual_realizado||0)}%`;return''}function bridgeAction(item){const p=item?.payload||{};if(item.entity==='tarefas_obra')return p.status==='concluida'?['Reabrir',{status:'aberta',concluido_em:null}]:['Concluir',{status:'concluida',concluido_em:new Date().toISOString()}];if(item.entity==='frentes_obra')return p.status==='concluida'?['Reabrir',{status:'ativa'}]:['Concluir',{status:'concluida'}];if(item.entity==='rdos')return p.status==='finalizado'?['Reabrir',{status:'rascunho'}]:['Finalizar',{status:'finalizado'}];if(item.entity==='cronograma_etapas'){const n=Math.min(100,Number(p.percentual_realizado||0)+10);return[`Avançar para ${n}%`,{percentual_realizado:n,status:n>=100?'concluido':p.status||'em_andamento'}]}return null}async function editBridge(item,patch){if(!window.mobileBridgeUpdate)return show('Seu perfil não pode alterar este item.');try{await window.mobileBridgeUpdate({entity:item.entity,localId:item.localId,sourceDeviceId:item.sourceDeviceId,patch});state=await window.multiuserReloadProject();renderObra360();show('Obra360 atualizado e enviado ao Desktop.')}catch(e){show(e?.message||'Não foi possível atualizar.')}}function renderObra360(){const bridge=state.desktopBridge||{},items=['fronts','tasks','rdos','schedule'].flatMap(k=>Array.isArray(bridge[k])?bridge[k]:[]).filter(x=>!x.deleted),conflicts=window.mobileSyncConflicts||[],today=getDay(localISODate(),false),active=(today.assignments||[]).filter(isActiveAssignment);content.innerHTML=`<section class="hero"><small>Operação integrada</small><div class="date">Obra360</div><div class="stats"><div class="stat"><strong>${active.length}</strong><span>frentes hoje</span></div><div class="stat"><strong>${items.length}</strong><span>itens do Desktop</span></div><div class="stat"><strong>${conflicts.length}</strong><span>conflitos</span></div></div></section><div class="quick-actions"><button class="quick-action" data-screen="floors"><strong>Pavimentos</strong><span>Etapas e checklists</span></button><button class="quick-action" data-screen="issues"><strong>Pendências</strong><span>Qualidade e bloqueios</span></button><button class="quick-action" data-screen="more"><strong>Planejamento</strong><span>Produtividade e previsão</span></button><button class="quick-action" data-screen="today"><strong>Dia</strong><span>Notas e apontamentos</span></button></div><section class="section"><div class="section-head"><div><h2>Do Desktop</h2><p>Frentes, tarefas, RDOs e planejamento sincronizados.</p></div></div>${items.map(item=>{const action=bridgeAction(item);return`<div class="card bridge-card"><div class="row"><div><span class="badge released">${bridgeLabel(item.entity)}</span><strong class="bridge-title">${esc(bridgeTitle(item))}</strong><div class="meta">${esc(bridgeMeta(item))}</div></div>${action?`<button class="linkbtn bridge-action" data-key="${esc(`${item.entity}:${item.localId}:${item.sourceDeviceId}`)}">${esc(action[0])}</button>`:''}</div></div>`}).join('')||'<div class="empty card">Nenhum item originado no Desktop aguardando operação mobile.</div>'}</section>${conflicts.length?`<section class="section"><div class="section-head"><div><h2>Conflitos</h2><p>Nada é sobrescrito sem decisão.</p></div></div>${conflicts.map(c=>`<div class="card conflict-card"><strong>${esc(bridgeLabel(c.entity))} #${esc(c.localId)}</strong><div class="meta">Desktop partiu da revisão ${esc(c.baseMobileRevision)}; Mobile já estava na ${esc(c.currentMobileRevision)}.</div>${window.mobileResolveConflict?`<div class="conflict-actions"><button class="linkbtn mobile-conflict" data-id="${c.id}" data-resolution="keep_mobile">Manter Mobile</button><button class="btn mobile-conflict" data-id="${c.id}" data-resolution="accept_desktop">Usar Desktop</button></div>`:''}</div>`).join('')}</section>`:''}`;document.querySelectorAll('.bridge-action').forEach(b=>b.addEventListener('click',()=>{const item=items.find(x=>`${x.entity}:${x.localId}:${x.sourceDeviceId}`===b.dataset.key),action=item&&bridgeAction(item);if(item&&action)void editBridge(item,action[1])}));document.querySelectorAll('.mobile-conflict').forEach(b=>b.addEventListener('click',async()=>{try{await window.mobileResolveConflict(b.dataset.id,b.dataset.resolution);state=await window.multiuserReloadProject();renderObra360();show('Conflito resolvido.')}catch(e){show(e?.message||'Não foi possível resolver.')}}))}function renderManagement(){const summary=window.mobileReadOnlySummary||{},html=window.mobileManagementHtml?window.mobileManagementHtml(summary,window.multiuserContext?.bootstrap?.access):'<div class="empty card">Resumo indisponível.</div>';content.innerHTML=`<section class="hero management-hero"><small>Consulta executiva</small><div class="date">Gestão</div><p>Somente visualização no celular. Cadastros e alterações permanecem no Desktop.</p></section><section class="section"><div class="section-head"><div><h2>Indicadores</h2><p>${summary.generatedAt?`Atualizados pelo Desktop em ${esc(new Date(summary.generatedAt).toLocaleString('pt-BR'))}`:'Aguardando o próximo sincronismo do Desktop.'}</p></div></div><div class="management-grid">${html}</div></section>`}function render(){nav();if(screen==='today')renderDay();if(screen==='obra360')renderObra360();if(screen==='floors')selectedFloor!==null?renderFloor():renderFloors();if(screen==='team')renderTeam();if(screen==='issues')renderIssues();if(screen==='more')renderMore();if(screen==='settings')renderSettings();if(screen==='management')renderManagement()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-screen]');if(!b)return;screen=b.dataset.screen;selectedFloor=null;render()});if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{}));state=await load();render();